set local role authenticated;
set local request.jwt.claims='{"sub":"31000000-0000-0000-0000-000000000001","role":"authenticated"}';
select public.recalculate_attendance_week('81000000-0000-4000-8000-000000000001');
do $$ declare r public.daily_attendance_results; begin
 select * into r from daily_attendance_results where is_current and work_date='2026-09-07' and company_id='11000000-0000-0000-0000-000000000001';
 if r.worked_seconds<>28500 or r.break_seconds<>3600 or r.late_seconds<>300 or r.early_leave_seconds<>1800 or (r.calculation->>'short_hours_seconds')::integer<>2100 or r.expected_punch_count<>4 or r.actual_break_out is null then raise exception 'Four punch / short-hours result mismatch: %',to_jsonb(r); end if;
 select * into r from daily_attendance_results where is_current and work_date='2026-09-08' and company_id='11000000-0000-0000-0000-000000000001';
 if r.worked_seconds<>25200 or r.break_seconds<>3600 or r.overtime_candidate_seconds<>0 then raise exception 'Cross-midnight result mismatch'; end if;
 if exists(select 1 from daily_attendance_results where is_current and company_id='11000000-0000-0000-0000-000000000001' and work_date between '2026-09-09' and '2026-09-12' and (worked_seconds is not null or payable_seconds is not null or recognised_paid_seconds<>0 or overtime_candidate_seconds<>0)) then raise exception 'Anomalous punches became payable'; end if;
 select * into r from daily_attendance_results where is_current and work_date='2026-09-13' and company_id='11000000-0000-0000-0000-000000000001';
 if r.overtime_candidate_seconds<>3600 or r.overtime_seconds<>0 then raise exception 'OT pending/approved split mismatch'; end if;
 if exists(select 1 from daily_attendance_results where is_current and company_id='11000000-0000-0000-0000-000000000001' and (holiday_normal_equivalent_seconds is not null or paid_break_seconds>0)) then raise exception 'Break or PPH was paid automatically'; end if;
 raise notice 'PASS four points, net work, late+early, midnight, duplicate, missing, typed order, extra punch, pending OT and blank PPH';
end $$;
